mapper.select:
SELECT id, order_no, user_id, seckill_id, product_id, seckill_price,
       quantity, total_amount, status, pay_time, pay_expire_time,
       transaction_id, pay_method, cancel_time, cancel_reason,
       is_deleted, create_time, update_time
FROM t_seckill_order
WHERE is_deleted = 0

    AND user_id = #{userId}


    AND seckill_id = #{seckillId}


    AND status = #{status}

ORDER BY create_time DESC
